const computeCompleteness = (metadata) => {
  const required = ["documentNo", "documentType", "version", "classification", "unit", "system", "device", "deviceType", "deviceTag"];
  const optional = ["publisher", "publishDate", "language", "keywords", "scope", "effectiveDate", "department"];
  const requiredScore = required.filter((k) => metadata[k]).length / required.length;
  const optionalScore = optional.filter((k) => metadata[k]).length / optional.length;
  return Math.round((requiredScore * 0.7 + optionalScore * 0.3) * 100);
};
