function inferPartCategory(name) {
  if (/螺栓|螺母|垫圈|销|键/.test(name)) return "紧固件";
  if (/阀|安全阀/.test(name)) return "阀门";
  if (/密封圈|密封垫|盘根/.test(name)) return "密封件";
  if (/灯|蓄电池|温度计|压力计|传感器|开关/.test(name)) return "电气仪表";
  if (/联轴器|轴承|皮带|齿轮/.test(name)) return "传动件";
  return "其他";
}
